const ui={zh:{title:'保存你的项目，随时继续。',intro:'使用邮箱注册。请点击邮件中的确认链接；以后可用邮箱和密码登录。',home:'返回首页',register:'注册',login:'登录',email:'邮箱',password:'密码（至少 8 位）',plainPassword:'密码',send:'发送确认邮件',projects:'你的项目',logout:'退出登录',signingOut:'正在退出…',newProject:'项目名称',create:'新建项目',note:'你的登录信息不会显示在网站页面中。中国区账户服务暂未启用。',sent:'确认邮件已发送，请点击邮件中的确认链接。',confirmed:'邮箱验证成功，请登录。',confirmFailed:'确认链接无效或已过期。请使用邮箱和密码登录。',welcome:'欢迎回来。',saved:'项目已保存。',empty:'还没有项目。你可以从首页的 AI 对话中保存项目，或在这里新建一个。',unavailable:'会员服务暂时不可用。',chats:'对话历史',account:'账户',openProject:'打开项目',openChat:'打开对话',projectsIntro:'打开项目后可继续对话或继续制作。',chatsIntro:'普通聊天会自动保存，可随时重新打开。',accountSummary:'会员账户已登录。你可以在这里管理语言和账户设置。',types:{visual:'视觉与海报',video:'视频与短片',writing:'写作与文案',presentation:'演示与汇报',knowledge:'问答与知识'}},en:{title:'Save your projects. Continue anytime.',intro:'Register with your email. Click the confirmation link in the email; later, sign in with your email and password.',home:'Home',register:'Register',login:'Sign in',email:'Email',password:'Password (at least 8 characters)',plainPassword:'Password',send:'Send confirmation email',projects:'Your projects',logout:'Sign out',signingOut:'Signing out…',newProject:'Project name',create:'Create project',note:'Your sign-in information is never shown on the website. China-region accounts are not active yet.',sent:'Confirmation email sent. Click the confirmation link in the email.',confirmed:'Email verified. Please sign in.',confirmFailed:'The confirmation link is invalid or expired. Please sign in with your email and password.',welcome:'Welcome back.',saved:'Project saved.',empty:'No projects yet. Save an AI conversation from the home page, or create one here.',unavailable:'Membership service is temporarily unavailable.',chats:'Chat history',account:'Account',openProject:'Open project',openChat:'Open chat',projectsIntro:'Open a project to continue the conversation or continue making.',chatsIntro:'Everyday chats save automatically and can be reopened anytime.',accountSummary:'You are signed in. Manage your language and account settings here.',types:{visual:'Visuals & posters',video:'Video & shorts',writing:'Writing & copy',presentation:'Presentation',knowledge:'Q&A & knowledge'}}};
let language=localStorage.getItem('ai-supermall-language')||'zh',authRevision=0,logoutInFlight=false;
const $=selector=>document.querySelector(selector);
const status=(message,ok=false)=>{const box=$('#accountStatus');box.textContent=message||'';box.classList.toggle('success',Boolean(ok));};
const request=async(path,options={})=>{const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||body.message||ui[language].unavailable);return body;};
function applyLanguage(next){language=next;localStorage.setItem('ai-supermall-language',next);document.documentElement.lang=next==='zh'?'zh-CN':'en';const t=ui[next];$('#pageTitle').textContent=t.title;$('#pageIntro').textContent=t.intro;$('#homeLink').textContent=t.home;$('#registerTab').textContent=t.register;$('#loginTab').textContent=t.login;$('#registerEmailLabel').textContent=t.email;$('#loginEmailLabel').textContent=t.email;$('#registerPasswordLabel').textContent=t.password;$('#loginPasswordLabel').textContent=t.plainPassword;$('#registerSubmit').textContent=t.send;$('#loginSubmit').textContent=t.login;$('#welcomeTitle').textContent=t.projects;$('#logoutButton').textContent=logoutInFlight?t.signingOut:t.logout;$('#projectTitle').placeholder=t.newProject;$('#projectSubmit').textContent=t.create;$('#accountNote').textContent=t.note;$('#languageToggle').textContent=next==='zh'?'EN':'中文';$('#memberProjectsLink').textContent=t.projects;$('#memberChatsLink').textContent=t.chats;$('#memberAccountLink').textContent=t.account;$('#projectsIntro').textContent=t.projectsIntro;$('#chatsTitle').textContent=t.chats;$('#chatsIntro').textContent=t.chatsIntro;$('#accountTitle').textContent=t.account;$('#accountSummary').textContent=t.accountSummary;}
function showTab(tab){$('#registerForm').hidden=tab!=='register';$('#loginForm').hidden=tab!=='login';$('#authTabs').hidden=false;document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===tab));}
function clearMemberView(){authRevision+=1;$('#memberArea').hidden=true;$('#memberEmail').textContent='';$('#projectList').replaceChildren();$('#chatList').replaceChildren();$('#projectsView').hidden=false;$('#chatsView').hidden=true;$('#accountView').hidden=true;$('#pageTitle').hidden=false;$('#pageIntro').hidden=false;$('#accountNote').hidden=false;}
function showMemberView(view){const projects=view==='projects',chats=view==='chats';$('#projectsView').hidden=!projects;$('#chatsView').hidden=!chats;$('#accountView').hidden=projects||chats;$('#memberProjectsLink').classList.toggle('active',projects);$('#memberChatsLink').classList.toggle('active',chats);$('#memberAccountLink').classList.toggle('active',!projects&&!chats);if(chats)loadConversations().catch(error=>status(error.message));}
function projectMeta(project){const items=Array.isArray(project?.conversation)?project.conversation:[],visual=items.find(item=>item?.type==='workspace_state'&&item.workspace==='visual'),meta=items.find(item=>item?.type==='project_meta'),workspace=visual?'visual':['visual','video','writing','presentation','knowledge'].includes(meta?.workspace)?meta.workspace:'knowledge';return{workspace,intent:['visual','video','writing','presentation','knowledge'].includes(meta?.intent)?meta.intent:workspace};}
function projectHref(project){const {workspace}=projectMeta(project);if(workspace==='visual')return`create-visual.html?project=${encodeURIComponent(project.id)}`;if(['video','writing','presentation'].includes(workspace))return`create-${workspace}.html?project=${encodeURIComponent(project.id)}`;return`index.html?project=${encodeURIComponent(project.id)}`;}
async function loadProjects(){if(window.aiSuperMallMemberList?.projects)return window.aiSuperMallMemberList.projects();const revision=authRevision,data=await request('/api/member/projects');if(revision!==authRevision||$('#memberArea').hidden)return;const list=$('#projectList');list.replaceChildren();if(!data.length){list.textContent=ui[language].empty;return;}data.forEach(project=>{const item=document.createElement('div'),name=document.createElement('strong'),kind=document.createElement('small'),time=document.createElement('small'),open=document.createElement('a'),meta=projectMeta(project);item.className='project-item';name.textContent=project.title;kind.textContent=ui[language].types[meta.intent];time.textContent=new Date(project.updated_at).toLocaleString(language==='zh'?'zh-CN':'en-US');open.className='project-open';open.href=projectHref(project);open.textContent=ui[language].openProject;item.append(name,kind,time,open);list.append(item);});}
async function loadConversations(){if(window.aiSuperMallMemberList?.history)return window.aiSuperMallMemberList.history();const revision=authRevision,data=await request('/api/member/conversations');if(revision!==authRevision||$('#memberArea').hidden)return;const list=$('#chatList');list.replaceChildren();if(!data.length){list.textContent=language==='zh'?'还没有对话。回到首页问一个问题后，它会自动保存在这里。':'No chats yet. Ask a question from Home and it will be saved here automatically.';return;}data.forEach(chat=>{const item=document.createElement('div'),name=document.createElement('strong'),time=document.createElement('small'),open=document.createElement('a');item.className='project-item';name.textContent=chat.title;time.textContent=new Date(chat.updated_at).toLocaleString(language==='zh'?'zh-CN':'en-US');open.className='project-open';open.href=`index.html?conversation=${encodeURIComponent(chat.id)}`;open.textContent=ui[language].openChat;item.append(name,time,open);list.append(item);});}
async function signedIn(){const revision=++authRevision;try{const user=await request('/api/account/me');if(revision!==authRevision)return;$('#memberEmail').textContent=user.email;$('#authTabs').hidden=true;$('#registerForm').hidden=true;$('#loginForm').hidden=true;$('#memberArea').hidden=false;$('#pageTitle').hidden=true;$('#pageIntro').hidden=true;$('#accountNote').hidden=true;const view=new URLSearchParams(location.search).get('view');showMemberView(view==='projects'||view==='chats'?view:'account');status(ui[language].welcome,true);await loadProjects();}catch{if(revision===authRevision){clearMemberView();showTab(new URLSearchParams(location.search).get('mode')==='register'?'register':'login');}}}
async function clearPrivateBrowserState(){localStorage.removeItem('ai-supermall-visual-draft-pending');sessionStorage.removeItem('ai-supermall-workspace-handoff');sessionStorage.removeItem('ai-supermall-post-login-return');sessionStorage.removeItem('ai-supermall-writing-draft');sessionStorage.removeItem('ai-supermall-presentation-draft');sessionStorage.removeItem('ai-supermall-video-draft');try{indexedDB.deleteDatabase('ai-supermall-visual-drafts');indexedDB.deleteDatabase('ai-supermall-video-drafts');}catch{}}
$('#languageToggle').onclick=()=>applyLanguage(language==='zh'?'en':'zh');document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{showTab(button.dataset.tab);status('');});
$('#registerForm').onsubmit=async event=>{event.preventDefault();try{await request('/api/account/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#registerEmail').value,password:$('#registerPassword').value})});status(ui[language].sent,true);}catch(error){status(error.message);}};
$('#loginForm').onsubmit=async event=>{event.preventDefault();try{await request('/api/account/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});await signedIn();}catch(error){status(error.message);}};
async function performSignOut(event){event?.preventDefault();if(logoutInFlight)return;logoutInFlight=true;const button=$('#logoutButton');button.disabled=true;applyLanguage(language);status(ui[language].signingOut);try{await request('/api/account/logout',{method:'POST'});await clearPrivateBrowserState();clearMemberView();showTab('login');history.replaceState(null,'',`${location.pathname}?mode=login`);status('');}catch(error){status(error.message);logoutInFlight=false;button.disabled=false;applyLanguage(language);}}
window.aiSuperMallSignOut=performSignOut;$('#logoutButton').onclick=performSignOut;
$('#projectForm').onsubmit=async event=>{event.preventDefault();const button=$('#projectSubmit');button.disabled=true;try{await request('/api/member/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:$('#projectTitle').value.trim(),locale:language,conversation:[]})});$('#projectTitle').value='';await loadProjects();status(ui[language].saved,true);}catch(error){status(error.message);}finally{button.disabled=false;}};
$('#memberProjectsLink').onclick=event=>{event.preventDefault();history.replaceState(null,'','?view=projects');showMemberView('projects');loadProjects().catch(error=>status(error.message));};$('#memberChatsLink').onclick=event=>{event.preventDefault();history.replaceState(null,'','?view=chats');showMemberView('chats');};$('#memberAccountLink').onclick=event=>{event.preventDefault();history.replaceState(null,'','?view=account');showMemberView('account');};
async function finishEmailConfirmation(){const params=new URLSearchParams(location.hash.slice(1));const token=params.get('access_token'),failed=params.get('error');if(!token&&!failed)return false;history.replaceState(null,'',location.pathname);showTab('login');status(token?ui[language].confirmed:ui[language].confirmFailed,Boolean(token));return true;}
(async()=>{applyLanguage(language);if(await finishEmailConfirmation())return;await signedIn();})();
